// HTML Encode/Decode

var text = input.get("text");
var mode = input.get("mode") || "encode";
var encodeQuotes = input.get("encodeQuotes") !== "false";
var encodeAll = input.get("encodeAllCharacters") === "true";

// Named HTML entities
var entities = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
    '\u00A0': '&nbsp;',
    '\u00A9': '&copy;',
    '\u00AE': '&reg;',
    '\u2122': '&trade;',
    '\u20AC': '&euro;',
    '\u00A3': '&pound;',
    '\u00A5': '&yen;',
    '\u00A2': '&cent;',
    '\u2013': '&ndash;',
    '\u2014': '&mdash;',
    '\u2018': '&lsquo;',
    '\u2019': '&rsquo;',
    '\u201C': '&ldquo;',
    '\u201D': '&rdquo;',
    '\u2022': '&bull;',
    '\u2026': '&hellip;'
};

// Reverse mapping
var reverseEntities = {};
for (var char in entities) {
    reverseEntities[entities[char]] = char;
}

// Add numeric entities for common chars
reverseEntities['&#38;'] = '&';
reverseEntities['&#60;'] = '<';
reverseEntities['&#62;'] = '>';
reverseEntities['&#34;'] = '"';
reverseEntities['&#39;'] = "'";
reverseEntities['&#160;'] = '\u00A0';

if (!text && text !== "") {
    log.error("Text input is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Text input is required");
    output.set("Result", "");
    tags.trigger("error");
} else {
    try {
        var result = text;
        var changedCount = 0;

        if (mode === "encode") {
            if (encodeAll) {
                // Encode all non-ASCII and special characters
                var encoded = "";
                for (var i = 0; i < text.length; i++) {
                    var char = text[i];
                    var code = text.charCodeAt(i);
                    if (entities[char]) {
                        encoded += entities[char];
                        changedCount++;
                    } else if (code > 127) {
                        encoded += '&#' + code + ';';
                        changedCount++;
                    } else {
                        encoded += char;
                    }
                }
                result = encoded;
            } else {
                // Basic encoding: & < > and optionally quotes
                result = result.replace(/&/g, function() { changedCount++; return '&amp;'; });
                result = result.replace(/</g, function() { changedCount++; return '&lt;'; });
                result = result.replace(/>/g, function() { changedCount++; return '&gt;'; });
                if (encodeQuotes) {
                    result = result.replace(/"/g, function() { changedCount++; return '&quot;'; });
                    result = result.replace(/'/g, function() { changedCount++; return '&#39;'; });
                }
            }
        } else {
            // Decode mode
            // First handle named entities
            for (var entity in reverseEntities) {
                var regex = new RegExp(entity.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
                var before = result;
                result = result.replace(regex, reverseEntities[entity]);
                if (result !== before) {
                    changedCount += (before.length - result.length) / (entity.length - 1);
                }
            }

            // Handle numeric entities (decimal)
            result = result.replace(/&#(\d+);/g, function(match, num) {
                changedCount++;
                return String.fromCharCode(parseInt(num, 10));
            });

            // Handle numeric entities (hex)
            result = result.replace(/&#x([0-9a-fA-F]+);/g, function(match, hex) {
                changedCount++;
                return String.fromCharCode(parseInt(hex, 16));
            });
        }

        output.set("Result", result);
        output.set("OriginalLength", text.length);
        output.set("ResultLength", result.length);
        output.set("ChangedCount", Math.floor(changedCount));
        output.set("Mode", mode);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");

        log.info(mode + "d HTML: " + Math.floor(changedCount) + " entities");
        tags.trigger("success");

    } catch (ex) {
        log.error("HTML " + mode + " failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Result", "");
        tags.trigger("error");
    }
}
